import {
    BooleanColumn,
    IntegerColumn,
    StringColumn,
    Table,
    Record,
    ChoiceColumn,
    GenericColumn,
    type Data,
    type TableName,
} from '../../db'

const MyTableSchema = Table({
    name: 'sys_my_table',
    schema: {
        strChoice: StringColumn({
            choices: {
                one: { label: '1' },
                two: { label: '2' },
            },
        }),
    },
})

const MyOtherTableSchema = Table({
    name: 'x_my_table',
    schema: {
        str: StringColumn({
            label: 'Any string',
        }),
    },
})

const MyOtherOtherTableSchema = Table({
    name: 'sys_my_other_table',
    schema: {
        numChoice: IntegerColumn({
            label: 'Number Column',
            choices: { 1: { label: '1' }, 2: { label: '2' } },
        }),
        bool: BooleanColumn({
            mandatory: true,
        }),
    },
})

const ChoiceTable = Table({
    name: 'choice_table',
    extends: 'name',
    schema: {
        choice: ChoiceColumn({
            dropdown: 'suggestion',
            choices: {
                one: { label: '1' },
            },
        }),
        choice2: ChoiceColumn({
            choices: {
                one: { label: '1' },
            },
        }),
        string: StringColumn({
            dropdown: 'suggestion',
            choices: {
                one: { label: '1' },
            },
        }),
        string2: StringColumn({
            choices: {
                one: { label: '1' },
            },
        }),
        string3: StringColumn({
            dropdown: 'none',
            choices: {
                one: { label: '1' },
            },
        }),
        integer: IntegerColumn({
            dropdown: 'suggestion',
            choices: {
                0: { label: '1' },
            },
        }),
        integer2: IntegerColumn({
            dropdown: 'none',
            choices: {
                1: { label: '1' },
            },
        }),
        generic: GenericColumn({
            columnType: 'generic',
            dropdown: 'suggestion',
            choices: {
                one: { label: '1' },
            },
        }),
        generic2: GenericColumn({
            columnType: 'generic',
            choices: {
                one: { label: 'one' },
            },
        }),
    },
})

declare global {
    namespace Now {
        namespace Internal {
            namespace TableSchemas {
                interface MyTable extends Helper<typeof MyTableSchema> {}
                interface MyOtherTable extends Helper<typeof MyOtherTableSchema> {}
                interface MyOtherOtherTable extends Helper<typeof MyOtherOtherTableSchema> {}
                interface ChoiceTable extends Helper<typeof ChoiceTable> {}
            }

            interface Tables {
                sys_my_table: Table<TableSchemas.MyTable>
                x_my_table: Table<TableSchemas.MyOtherTable>
                sys_my_other_table: Table<TableSchemas.MyOtherOtherTable>
                choice_table: Table<TableSchemas.ChoiceTable>
            }
        }
    }
}

Record({
    $id: 0,
    table: 'sys_my_table',
    data: {
        strChoice: 'two',
    },
})

Record({
    $id: 0,
    table: 'sys_my_table',
    data: {
        // @ts-expect-error Wrong choice value for `strChoice`
        strChoice: 'three',
    },
})

Record({
    $id: 1,
    table: 'x_my_table',
    data: {
        // @ts-expect-error Wrong type for `str`
        str: 123,
    },
})

Record({
    $id: 2,
    table: 'sys_my_other_table',
    // @ts-expect-error Missing required column `bool`
    data: {
        numChoice: 1,
    },
})

Record({
    $id: 2,
    table: 'sys_my_other_table',
    data: {
        bool: true,
        numChoice: 2,
    },
})

Record({
    $id: 2,
    table: 'sys_my_other_table',
    data: {
        bool: true,
        // @ts-expect-error Wrong choice value for `numChoice`
        numChoice: 3,
    },
})

Record({
    $id: 0,
    table: 'sys_my_table',
    data: {
        strChoice: 'one',
    },
})

Record({
    $id: 1,
    table: 'x_my_table',
    data: {
        str: 'Hello',
    },
})

Record({
    $id: 2,
    table: 'sys_my_other_table',
    data: {
        bool: true,
        numChoice: 1,
    },
})

Record({
    table: 'choice_table',
    $id: 0,
    data: {
        choice: 'two',
        // @ts-expect-error Wrong choice value for non-`suggestion` dropdown
        choice2: 'two',
        string: 'two',
        // @ts-expect-error Wrong choice value for non-`suggestion` dropdown
        string2: 'two',
        // @ts-expect-error Wrong choice value for non-`suggestion` dropdown
        string3: 'two',
        integer: 1,
        // @ts-expect-error Wrong choice value for non-`suggestion` dropdown
        integer2: 2,
        generic: 'two',
        // @ts-expect-error Wrong choice value for non-`suggestion` dropdown
        generic2: 'two',
    },
})

declare function query<const T extends TableName, const C extends keyof Data<T>>(
    table: T,
    column: C,
    value: Data<T>[C]
): void

// OK
query('x_my_table', 'str', 'Hello')

// OK
query('x_my_table', 'str', undefined)

// @ts-expect-error Wrong type for value
query('x_my_table', 'str', 123)

// @ts-expect-error Column does not exist
query('x_my_table', 'non_existent_column', 123)

// OK
query('non_existent_table', 'str', 'Hello')

// OK
query('non_existent_table', 'str', undefined)

// OK
query('non_existent_table', 'str', 123)
